import React, { useState } from 'react';
import { UserInput, GeneratedResume, AppState } from './types';
import ResumeForm from './components/ResumeForm';
import ResumePreview from './components/ResumePreview';
import { generateResumeContent } from './services/geminiService';
import { Sparkles, AlertCircle } from 'lucide-react';

const initialInput: UserInput = {
  fullName: '',
  email: '',
  phone: '',
  linkedin: '',
  jobTitle: '',
  experienceLevel: 'Mid Level',
  skills: '',
  experience: '',
  education: '',
  projects: '',
};

function App() {
  const [appState, setAppState] = useState<AppState>(AppState.EDITING);
  const [inputData, setInputData] = useState<UserInput>(initialInput);
  const [resumeData, setResumeData] = useState<GeneratedResume | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING);
    setError(null);
    try {
      const result = await generateResumeContent(inputData);
      setResumeData(result);
      setAppState(AppState.VIEWING);
    } catch (err) {
      console.error(err);
      setError("Failed to generate resume. Please ensure all fields contain valid information and try again.");
      setAppState(AppState.EDITING);
    }
  };

  const handleEdit = () => {
    setAppState(AppState.EDITING);
  };

  return (
    <div className="min-h-screen bg-gray-100 print:bg-white">
      {/* Navbar - hidden on print */}
      <nav className="no-print bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <Sparkles className="h-8 w-8 text-sky-600" />
              <span className="ml-2 text-xl font-bold text-gray-900 tracking-tight">Resume Architect</span>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 print:p-0 print:max-w-none">

        {error && (
          <div className="no-print mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3 text-red-700">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div>
              <h4 className="font-semibold">Error</h4>
              <p className="text-sm">{error}</p>
            </div>
          </div>
        )}

        {appState === AppState.EDITING || appState === AppState.GENERATING ? (
          <div className="max-w-3xl mx-auto animate-in fade-in duration-500">
            <div className="mb-6 text-center">
              <h1 className="text-3xl font-extrabold text-gray-900 sm:text-4xl">
                Build your perfect resume
              </h1>
              <p className="mt-3 text-lg text-gray-500">
                Enter your messy notes, and let AI structure them into a professional, ATS-optimized document.
              </p>
            </div>
            <ResumeForm 
              input={inputData} 
              setInput={setInputData} 
              onGenerate={handleGenerate}
              isGenerating={appState === AppState.GENERATING}
            />
          </div>
        ) : (
          resumeData && (
            <div className="animate-in slide-in-from-bottom-4 duration-700">
              <ResumePreview 
                data={resumeData} 
                personalInfo={inputData} 
                onEdit={handleEdit} 
              />
            </div>
          )
        )}
      </main>

      {/* Footer */}
      <footer className="no-print bg-white border-t border-gray-200 mt-12 py-8">
        <div className="max-w-5xl mx-auto px-4 text-center text-gray-400 text-sm">
          <p>© {new Date().getFullYear()} Resume Architect.</p>
        </div>
      </footer>
    </div>
  );
}

export default App;

import React from 'react';
import { GeneratedResume, UserInput } from '../types';
import { Mail, Phone, Link as LinkIcon, Download, ArrowLeft, FileText } from 'lucide-react';

interface ResumePreviewProps {
  data: GeneratedResume;
  personalInfo: UserInput;
  onEdit: () => void;
}

const ResumePreview: React.FC<ResumePreviewProps> = ({ data, personalInfo, onEdit }) => {
  const handlePrint = () => {
    window.print();
  };

  const handleDownloadTxt = () => {
    const { fullName, email, phone, linkedin, jobTitle } = personalInfo;
    const { professionalSummary, skills, workExperience, education, projects } = data;

    let content = `${fullName.toUpperCase()}\n${jobTitle}\n`;
    content += `${[email, phone, linkedin].filter(Boolean).join(' | ')}\n\n`;

    content += `PROFESSIONAL SUMMARY\n${'-'.repeat(20)}\n${professionalSummary}\n\n`;

    content += `SKILLS\n${'-'.repeat(6)}\n`;
    skills.forEach(s => {
      content += `${s.category}: ${s.items.join(', ')}\n`;
    });
    content += '\n';

    content += `EXPERIENCE\n${'-'.repeat(10)}\n`;
    workExperience.forEach(job => {
      content += `${job.role} at ${job.company}\n`;
      content += `${job.duration} | ${job.location}\n`;
      job.points.forEach(p => content += `• ${p}\n`);
      content += '\n';
    });

    content += `EDUCATION\n${'-'.repeat(9)}\n`;
    education.forEach(edu => {
      content += `${edu.degree}\n${edu.institution}, ${edu.year}\n`;
      if (edu.details) content += `${edu.details}\n`;
      content += '\n';
    });

    if (projects && projects.length > 0) {
      content += `PROJECTS\n${'-'.repeat(8)}\n`;
      projects.forEach(proj => {
        content += `${proj.name} (${proj.technologies.join(', ')})\n`;
        content += `${proj.description}\n\n`;
      });
    }

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fullName.replace(/\s+/g, '_')}_Resume.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col gap-6">
      {/* Actions Bar */}
      <div className="no-print bg-white p-4 rounded-xl shadow-sm border border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4 sticky top-4 z-10">
