import { Mail, Phone, Link as LinkIcon, Download, ArrowLeft, FileText, Loader2 } from 'lucide-react';

interface ResumePreviewProps {
  data: GeneratedResume;
  personalInfo: UserInput;
  onEdit: () => void;
}

declare global {
  interface Window {
    html2pdf: any;
  }
}

const ResumePreview: React.FC<ResumePreviewProps> = ({ data, personalInfo, onEdit }) => {
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownloadPdf = async () => {
    setIsDownloading(true);
    const element = document.getElementById('resume-preview-content');

    if (element && window.html2pdf) {
      // Create a clone to render at exact A4 width, solving mobile blurriness
      const clone = element.cloneNode(true) as HTMLElement;

      // Force A4 width (210mm approx 794px at 96dpi)
      // We set it slightly larger to ensure high quality text rendering
      clone.style.width = '210mm';
      clone.style.minHeight = '297mm';
      clone.style.padding = '0'; // We handle padding inside or rely on existing classes, but let's ensure it fits
      clone.style.position = 'absolute';
      clone.style.left = '-9999px';
      clone.style.top = '0';
      // Remove shadows for a cleaner PDF print
      clone.classList.remove('shadow-xl', 'mx-auto');
      clone.classList.add('bg-white');

      document.body.appendChild(clone);

      const opt = {
        margin: 0,
        filename: `${personalInfo.fullName.replace(/\s+/g, '_')}_Resume.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { 
          scale: 3, // Higher scale for clear text
          useCORS: true, 
          letterRendering: true,
          windowWidth: 794 // Force desktop width resolution
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      try {
        await window.html2pdf().set(opt).from(clone).save();
      } catch (error) {
        console.error("PDF generation failed", error);
        window.print();
      } finally {
        document.body.removeChild(clone);
        setIsDownloading(false);
      }
    } else {
      // Fallback
      window.print();
      setIsDownloading(false);
    }
  };

  const handleDownloadTxt = () => {
    const { fullName, email, phone, linkedin, jobTitle } = personalInfo;
    const { professionalSummary, skills, workExperience, education, projects } = data;

    let content = `${fullName.toUpperCase()}\n${jobTitle}\n`;
    content += `${[email, phone, linkedin].filter(Boolean).join(' | ')}\n\n`;

    content += `PROFESSIONAL SUMMARY\n${'-'.repeat(20)}\n${professionalSummary}\n\n`;

    content += `SKILLS\n${'-'.repeat(6)}\n`;
    skills.forEach(s => {
      content += `${s.category}: ${s.items.join(', ')}\n`;
    });
    content += '\n';

    content += `EXPERIENCE\n${'-'.repeat(10)}\n`;
    workExperience.forEach(job => {
      content += `${job.role} at ${job.company}\n`;
      content += `${job.duration} | ${job.location}\n`;
      job.points.forEach(p => content += `• ${p}\n`);
      content += '\n';
    });

    content += `EDUCATION\n${'-'.repeat(9)}\n`;
    education.forEach(edu => {
      content += `${edu.degree}\n${edu.institution}, ${edu.year}\n`;
      if (edu.details) content += `${edu.details}\n`;
      content += '\n';
