import { GoogleGenAI, Type, Schema } from "@google/genai";
import { UserInput, GeneratedResume } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const resumeSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    professionalSummary: {
      type: Type.STRING,
      description: "A compelling 3-4 line professional summary optimized for ATS.",
    },
    workExperience: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          role: { type: Type.STRING },
          company: { type: Type.STRING },
          location: { type: Type.STRING },
          duration: { type: Type.STRING },
          points: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Action-oriented bullet points using strong verbs.",
          },
        },
        required: ["role", "company", "duration", "points"],
      },
    },
    skills: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, description: "e.g., Technical, Soft Skills, Tools" },
          items: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["category", "items"],
      },
    },
    education: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          degree: { type: Type.STRING },
          institution: { type: Type.STRING },
          location: { type: Type.STRING },
          year: { type: Type.STRING },
          details: { type: Type.STRING },
        },
        required: ["degree", "institution", "year"],
      },
    },
    projects: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          description: { type: Type.STRING },
          technologies: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "description"],
      },
    },
  },
  required: ["professionalSummary", "workExperience", "skills", "education"],
};

export const generateResumeContent = async (input: UserInput): Promise<GeneratedResume> => {
  const prompt = `
    You are a professional resume writer and HR expert.
    Create a modern, ATS-friendly resume based on the information provided below.

    Rules:
    - Use clear, professional English
    - Avoid unnecessary words
    - Optimize for Applicant Tracking Systems (ATS)
    - Use strong action verbs (e.g., Spearheaded, Orchestrated, Developed)
    - Do not fabricate fake experience, but polish the existing input to sound professional.
    - Make it suitable for international job markets.

    Input Data:
    Full Name: ${input.fullName}
    Job Title: ${input.jobTitle}
    Experience Level: ${input.experienceLevel}
    GitHub: ${input.github}
    Portfolio/Website: ${input.website}
    Skills: ${input.skills}
    Work Experience Input: ${input.experience}
    Education Input: ${input.education}
    Projects Input: ${input.projects}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: resumeSchema,
        temperature: 0.4, // Keep it relatively deterministic but creative enough for phrasing
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GeneratedResume;
  } catch (error) {
    console.error("Error generating resume:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { GeneratedResume, UserInput } from '../types';
import { Mail, Phone, Link as LinkIcon, Download, ArrowLeft, FileText, Loader2, Github, Globe } from 'lucide-react';

interface ResumePreviewProps {
  data: GeneratedResume;
  personalInfo: UserInput;
  onEdit: () => void;
}

declare global {
  interface Window {
    html2pdf: any;
  }
}

const ResumePreview: React.FC<ResumePreviewProps> = ({ data, personalInfo, onEdit }) => {
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownloadPdf = async () => {
    setIsDownloading(true);
    // Find the original element
    const element = document.getElementById('resume-preview-content');

    if (element && window.html2pdf) {
      // 1. Clone the element
      const clone = element.cloneNode(true) as HTMLElement;

      // 2. Style the clone to be "visible" to the generator but hidden from the user
      // Placing it at top:0 left:0 with negative z-index is safer than -9999px
      clone.style.cssText = `
        position: absolute;
        top: 0;
        left: 0;
        width: 210mm; /* A4 width */
        min-height: 297mm; /* A4 height */
        background-color: white;
        z-index: -9999;
        pointer-events: none;
        margin: 0;
        box-sizing: border-box;
      `;

      // Remove classes that might interfere with exact positioning (like mx-auto for centering)
      clone.classList.remove('shadow-xl', 'mx-auto', 'print-container');
      clone.classList.add('bg-white'); // Ensure white background

      // 3. Append to body so it renders
      document.body.appendChild(clone);

      // 4. Wait a moment for styles to apply and images/fonts to settle
      await new Promise(resolve => setTimeout(resolve, 500));

      const opt = {
        margin: 0,
        filename: `${personalInfo.fullName.replace(/\s+/g, '_')}_Resume.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { 
          scale: 2, // Good balance of quality and file size
          useCORS: true, 
          letterRendering: true,
          scrollY: 0, // Capture from the top of the clone
          windowWidth: 794 // 210mm @ 96 DPI
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      try {
        await window.html2pdf().set(opt).from(clone).save();
      } catch (error) {
        console.error("PDF generation failed", error);
        alert("PDF generation encountered an error. Printing fallback will be used.");
        window.print();
      } finally {
        // 5. Cleanup
        if (document.body.contains(clone)) {
          document.body.removeChild(clone);
        }
        setIsDownloading(false);
      }
    } else {
      // Fallback
      window.print();
      setIsDownloading(false);
    }
  };

