      container.appendChild(clone);
      document.body.appendChild(container);

      // Scroll to top to ensure capture starts correctly
      window.scrollTo(0, 0);

      // 5. Wait for layout and fonts
      await new Promise(resolve => setTimeout(resolve, 800));

